{"command": "cat > /prediction.json << 'JSONEOF'
{
    "vllm/v1/worker/gpu/sampler.py": {
        "_gumbel_sample_kernel": "@triton.jit\ndef _gumbel_sample_kernel(\n    local_argmax_ptr,\n    local_argmax_stride,\n    local_max_ptr,\n    local_max_stride,\n    logits_ptr,\n    logits_stride,\n    seeds_ptr,\n    pos_ptr,\n    is_greedy_ptr,\n    vocab_size,\n    BLOCK_SIZE: tl.constexpr,\n):\n    req_idx = tl.program_id(0)\n    block_idx = tl.program_id(1)\n    \n    is_greedy = tl.load(is_greedy_ptr + req_idx)\n    \n    # Compute the vocabulary range for this block\n    block_start = block_idx * BLOCK_SIZE\n    block = block_start + tl.arange(0, BLOCK_SIZE)\n    mask = block < vocab_size\n    \n    if is_greedy:\n        # Greedy sampling. Don't apply gumbel noise.\n        logits = tl.load(\n            logits_ptr + req_idx * logits_stride + block,\n            mask=mask,\n            other=float(\"-inf\"),\n        )\n        \n        # Find local max and argmax within this block\n        local_max = tl.max(logits, axis=0)\n        local_argmax = tl.argmax(logits, axis=0)\n        local_argmax = block_start + local_argmax\n        \n        # Handle the case where all values are -inf (no valid tokens)\n        local_max = tl.where(tl.sum(mask.to(tl.int32)) > 0, local_max, float(\"-inf\"))\n        local_argmax = tl.where(tl.sum(mask.to(tl.int32)) > 0, local_argmax, 0)\n    else:\n        # Random sampling.\n        # Calculate gumbel seed.\n        seed = tl.load(seeds_ptr + req_idx)\n        pos = tl.load(pos_ptr + req_idx)\n        gumbel_seed = tl.randint(seed, pos)\n        \n        # Generate gumbel noise.\n        r = tl.rand(gumbel_seed, block).to(tl.float64)\n        gumbel_noise = -tl.log(-tl.log(r + 1e-20) + 1e-20)\n        gumbel_noise = gumbel_noise.to(tl.float32)\n        \n        # Apply gumbel noise.\n        logits = tl.load(logits_ptr + req_idx * logits_stride + block, mask=mask)\n        logits = tl.where(mask, logits + gumbel_noise, float(\"-inf\"))\n        \n        # Find local max and argmax within this block\n        local_max = tl.max(logits, axis=0)\n        local_argmax = tl.argmax(logits, axis=0)\n        local_argmax = block_start + local_argmax\n        \n        # Handle the case where all values are -inf (no valid tokens)\n        local_max = tl.where(tl.sum(mask.to(tl.int32)) > 0, local_max, float(\"-inf\"))\n        local_argmax = tl.where(tl.sum(mask.to(tl.int32)) > 0, local_argmax, 0)\n    \n    # Store local results\n    tl.store(local_max_ptr + req_idx * local_max_stride + block_idx, local_max)\n    tl.store(local_argmax_ptr + req_idx * local_argmax_stride + block_idx, local_argmax)",
        "gumbel_sample": "def gumbel_sample(\n    logits: torch.Tensor,  # [num_reqs, vocab_size]\n    is_greedy: torch.Tensor,  # [num_reqs]\n    seed: torch.Tensor,  # [num_reqs]\n    pos: torch.Tensor,  # [num_reqs]\n) -> torch.Tensor:\n    num_reqs, vocab_size = logits.shape\n    BLOCK_SIZE = 16384\n    num_blocks = triton.cdiv(vocab_size, BLOCK_SIZE)\n    \n    # Allocate buffers for local results\n    # local_max: [num_reqs, num_blocks]\n    # local_argmax: [num_reqs, num_blocks]\n    local_max = torch.empty(\n        num_reqs,\n        num_blocks,\n        dtype=torch.float32,\n        device=logits.device,\n    )\n    local_argmax = torch.empty(\n        num_reqs,\n        num_blocks,\n        dtype=torch.int64,\n        device=logits.device,\n    )\n    \n    # Launch kernel to compute per-block local max and argmax\n    _gumbel_sample_kernel[(num_reqs, num_blocks)](\n        local_argmax,\n        local_argmax.stride(0),\n        local_max,\n        local_max.stride(0),\n        logits,\n        logits.stride(0),\n        seed,\n        pos,\n        is_greedy,\n        vocab_size,\n        num_warps=8,\n        BLOCK_SIZE=BLOCK_SIZE,  # type: ignore\n    )\n    \n    # Global reduction: find the block with the maximum value, then get its argmax\n    # For each request, find which block has the max value\n    global_max_vals, global_max_block = torch.max(local_max, dim=1)\n    \n    # Gather the argmax from the winning block for each request\n    req_indices = torch.arange(num_reqs, device=logits.device)\n    sampled = local_argmax[req_indices, global_max_block]\n    \n    return sampled"
    }
}
JSONEOF
echo "Created prediction.json""}

